    cc_title: "Cost & margin calculator",
    cc_open: "Calculator",
    cc_hint: "Landing cost = what an item costs once it is in our warehouse (supplier price, transport, customs, excise, import VAT). Net cost = landing cost plus what the sale itself costs: commissions, overhead and taxes. Margin and net margin show what is left of the selling price. Everything is per item. Tap the gear for the rates, the costs and the full methodology.",
