    cc_method_workbook: "Workbook",
    cc_method_payer: "VAT payer",
    cc_method_hint: "Workbook: the workbook's way -- landing cost already contains the import VAT, then 20% VAT tax and 18% profit tax on the margin. VAT payer: KAD is a VAT payer, so import VAT is only advanced and is credited against the VAT collected from customers; profit tax is charged on the real profit. Prices include VAT. The payer method gives a lower net cost (the workbook counts VAT twice). The other method's result is always shown under the figures.",
