    cc_set_intro: "Changes apply at once and stay on this phone only. Defaults come from your ERP cash ledger (12 months to 2026-09) and the workbook.",
    cc_sec_rate: "Exchange rate",
    cc_sec_duties: "Customs duties & import taxes",
