    cc_set_vat: "Import VAT, %",
    cc_set_handling: "Clearance costs, USD per litre",
    cc_set_other: "Other costs, USD per item",
    cc_set_duties_note: "Duty and ecology are % of the customs value (supplier price + legal transport). Excise is per kg of net weight (550 x 1.24 in 2026). VAT is charged on value + duty + excise.",
    cc_set_transport_note: "Real = what the carrier is paid (not in the customs value). Legal = the freight on the customs invoice (raises the customs value, so duty, ecology and VAT). Orlen and Lotos come from one factory: one set of values.",
    cc_real: "Real",
    cc_legal: "Legal",
    cc_set_comm_director: "Sales director, % (every channel except KF and CAS)",
    cc_set_comm_rep: "Sales manager, % (own SM channel only)",
    cc_set_comm_note: "SM channels pay both (4%), CVO / PCO / OEM only the director's (2%), KF and CAS none. Products show the dearest case until you pick a channel.",
    cc_include_overhead: "Include overhead and costs in the net cost",
    cc_set_items_note: "Measured from the cash ledger (12 months, 320 M AMD of sales, 89,581 L). Fixed monthly costs are a share of the price; vehicle costs follow the litres. Switch items off, change them or add your own.",
