    cc_add_btn: "Add",
    cc_set_ptax: "Profit tax, %",
    cc_set_vattax: "VAT tax (workbook method), % of margin",
    cc_set_vatshare: "Import VAT share of landing cost (payer method, catalog items)",
    cc_reset: "Reset to defaults",
    cc_m_landing_h: "Landing cost: what a pack costs in our warehouse",
    cc_m_landing: "<p>Per item: supplier price + <b>legal transport</b> (the freight value declared on the customs invoice; part of the customs value) -> ecology 2% and customs duty 5% of that value -> excise 682 AMD per kg of net weight (550 x 1.24 indexation for 2026) -> import VAT 20% of (value + duty + excise) -> <b>real freight</b> (what the carrier is paid, USD per kg, not part of the customs value) -> clearance costs (broker, terminal, about 6 AMD per litre). Converted to AMD at the rate in Settings.</p><p>Checked against the 16 customs clearances in the Cashflow sheet (2025-05 to 2026-09): duty and ecology come out at about 5% and 2% of the value and excise at 608-679 AMD per kg, so these rules match what customs really charged.</p>",
    cc_m_commission_h: "Commissions by sales channel",
    cc_m_commission: "<p>2% of the selling price goes to the sales director on every channel except KF and CAS; another 2% goes to the sales manager of an \"SM\" channel (own channel only). So SM YVN / Shirak / Davtashen / B2B / SM CAS pay 4%, CVO / PCO / OEM 2%, KF and CAS 0%. Until a channel is chosen, the Products page and the discount floors use the dearest case, 4%.</p>",
    cc_m_overhead_h: "Overhead (replaces the flat 790 AMD per litre)",
    cc_m_overhead: "<p>Measured from the Cashflow sheet for the 12 full months 2025-10 to 2026-09: sales 320.1 M AMD, 89,581 litres, 1,537 orders (3,574 AMD per litre on average). Fixed monthly costs are spread as a <b>share of the selling price</b>: a litre sold at 9,000 AMD carries more of them than a litre sold at 2,400 AMD, which a per-litre figure cannot show. Payroll without commissions 8.22%, payroll taxes 1.43%, office and representation 4.61%, marketing 2.46%, ecology fee 0.54%, interest and bank fees 0.23% = <b>17.49%</b>.</p><p>Vehicle running costs follow the volume: fuel 34.3, maintenance 6.6 and depreciation 9.1 AMD per litre = <b>49.9 AMD per litre</b> (the new delivery vehicle is spread over 5 years).</p><p>Not counted as costs: purchases, customs payments (already in the landing cost), VAT (a pass-through), profit tax (computed separately), loan repayments, dividends and personal withdrawals, currency exchange and transfers.</p>",
    cc_m_transport_h: "Freight: real and legal",
    cc_m_transport: "<p><b>Real</b> = what the carriers are paid. From the ledger: Castrol via Sole Trans 0.25 USD/kg (3 shipments, 48 t), Royal on Luk Oil trucks about 0.40 USD/kg (3 shipments), Lotos / Orlen (one factory, one price) 0.325 USD/kg (1 shipment). <b>Legal</b> = the freight value on the customs invoice: it raises the customs value and so duty, ecology and VAT. Castrol 2,007 USD per 9,280 kg truck = 0.216 USD/kg; the other factories 0.35 USD/kg. The real values rest on few shipments: update them after every shipment.</p>",
    cc_m_taxes_h: "Taxes and the two methods",
    cc_m_taxes: "<p><b>Workbook method</b> (default): VAT tax = 20% of the margin (price - landing cost) and profit tax = 18% of the rest of the margin, added to landing cost (which already contains the import VAT), commissions and overhead.</p><p><b>VAT-payer method</b> (recommended once your accountant confirms): KAD is a VAT payer, so import VAT is only advanced and is credited against the VAT collected from customers. Prices include VAT: revenue without VAT = price / 1.2; VAT to the state = price - revenue without VAT - import VAT; profit tax = 18% x (revenue without VAT - landing cost without import VAT - commissions - overhead). The ledger agrees: in the same 12 months customs took 34 M AMD of import VAT, the monthly VAT returns 24 M, against 53 M of VAT inside the sales. The payer method lowers the net cost by about 6% (the workbook counts VAT twice). The calculator always shows the other method's result in one line. A catalog product's import VAT is estimated as 16% of its landing cost; a new pack uses the exact figure.</p>",
    cc_m_rate_h: "Exchange rate",
    cc_m_rate: "<p>The workbook uses 377.5 AMD per USD. The ledger's USD operations in June-September 2026 ran 366-370 (360 in October). A lower rate lowers landing costs by about 3%: tap \"Market now\" in the Rate section when you want replacement cost. Catalog products keep the Excel landing cost (made at 377.5) unless you type another one.</p>",
    cc_m_law_h: "Armenian law notes (confirm with your accountant)",
    cc_m_law: "<ul><li>VAT 20%. Registration is mandatory above 115 M AMD of annual turnover; KAD (320 M) is a VAT payer, and input VAT, import VAT included, is offset in the monthly return.</li><li>Profit tax 18%. Deductible: commissions, payroll, office, marketing, depreciation. Not deductible: VAT, dividends, loan principal.</li><li>Excise on lubricating oil: 550 AMD per kg x an annual coefficient (2024: 1.08, 2025: 1.16, 2026: 1.24 = 682). A new 2027-2029 excise schedule was adopted in July 2026 (from 1 February 2027): check whether the lubricant rate changes and update the field.</li><li>The customs value must include transport to the border: the legal freight on the invoice should not be lower than the freight really paid. Castrol: declared 0.216, real 0.252; Royal: declared 0.35, real 0.40; Lotos / Orlen: declared 0.35, real 0.325 (no issue). Ask your customs broker whether the difference is a risk.</li><li>The employer pays no social contribution; income tax is a flat 20% withheld from gross pay; a new compulsory health-insurance contribution applies from 2026.</li><li>Duty 5% and ecology 2% are confirmed by the customs payments in the ledger, not by the legislation text.</li></ul><p>These come from secondary sources: confirm the final figures with your accountant and customs broker.</p>",
    cc_m_limits_h: "What is estimated",
    cc_m_limits: "<ul><li>Real freight rests on 1-3 shipments per brand.</li><li>In the workbook commissions are paid on collections; here they are charged on sales.</li><li>Overhead is an average; one-off items (for example hosting the Castrol Turkey team) sit inside Office.</li><li>Credit-line interest hardly appears in the ledger (0.4 M AMD); the cost of money tied up in receivables (about 100 M AMD of debt) is not included: add it as your own cost if you want it.</li><li>No allowance for returns or bad debts.</li><li>Review the numbers every quarter.</li></ul>",
